/**
 * HTTP contract types for the `user-organization` service.
 *
 * Generated by reading the C# source in
 * /home/user/stockout/services/user-organization (see docs/contracts/user-organization.md).
 *
 * Serialization: ASP.NET Core web defaults (camelCase, nulls written, no enum converter).
 * All enum-like fields are plain strings in C#; they are modelled here as string-literal unions.
 * Guid -> string, DateTime -> ISO-8601 string (usually WITHOUT trailing "Z"; treat as UTC).
 */

// ---------------------------------------------------------------------------
// Primitive aliases
// ---------------------------------------------------------------------------

/** System.Guid serialized as lowercase hyphenated string. */
export type Guid = string;

/** System.DateTime serialized as ISO-8601. DB-sourced values have no "Z" suffix but are UTC. */
export type IsoDateTime = string;

// ---------------------------------------------------------------------------
// Envelopes & errors
// ---------------------------------------------------------------------------

/**
 * Success envelope.
 * C#: Emcore.UserOrganization.Contracts.Responses.ApiResponse<T> and the anonymous
 * `new { success = true, data = ... }` in BaseApiController.MapResult.
 */
export interface ApiResponse<T> {
  success: boolean;
  data: T;
}

/** Body of "void" success responses: `{ success: true, data: {} }`. C#: ApiResponse<object> with `new { }`. */
export type EmptyData = Record<string, never>;

/**
 * Error shape E1/E3. C#: Emcore.UserOrganization.Contracts.Responses.ErrorResponse
 * (also anonymous `{ Error, Message }` in AdminMarketplaceSellersController).
 * `message` is serialized as `null` when not set.
 */
export interface ErrorResponse {
  error: string;
  message: string | null;
}

/** Error shape E4. C#: anonymous `new { code = "MARKETPLACE_SELLER_ACCESS_DENIED" }`. */
export interface MarketplaceAccessDeniedError {
  code: 'MARKETPLACE_SELLER_ACCESS_DENIED';
}

/** `title` values in E2 ProblemDetails. C#: Emcore.BuildingBlocks.Core.ErrorType.ToString() (or "Error" if null). */
export type ResultErrorTitle = 'Failure' | 'Validation' | 'NotFound' | 'Conflict' | 'Forbidden' | 'Error';

/**
 * Error shape E2. C#: Microsoft.AspNetCore.Mvc.ProblemDetails from BaseApiController.MapResult.
 * NOTE: the internal Error.Code is NOT exposed; `detail` is Error.Message and is often "".
 */
export interface ResultProblemDetails {
  /** `https://emcore.platform/errors/{status}` */
  type: string;
  title: ResultErrorTitle;
  status: number;
  detail: string;
  traceId?: string;
}

/**
 * Error shape E5 (automatic [ApiController] model validation).
 * C#: Microsoft.AspNetCore.Mvc.ValidationProblemDetails. Keys of `errors` are C# PascalCase
 * property names (e.g. "Email", "RoleCodes") or JSON paths like "$.email".
 */
export interface ValidationProblemDetails {
  type: string;
  title: string;
  status: 400;
  errors: Record<string, string[]>;
  traceId?: string;
}

// ---------------------------------------------------------------------------
// String enums
// ---------------------------------------------------------------------------

/** System platform role codes. C#: Emcore.UserOrganization.Domain.Constants.PlatformRoleCodes. */
export type SystemPlatformRoleCode = 'PlatformSuperAdmin' | 'PlatformAdmin';

export const SYSTEM_ROLES = {
  PlatformSuperAdmin: 'PlatformSuperAdmin',
  PlatformAdmin: 'PlatformAdmin',
} as const satisfies Record<SystemPlatformRoleCode, SystemPlatformRoleCode>;

/** Invitation status (SQL PR_PLATFORM_INVITATION_LIST/GET; "Expired" is computed). */
export type PlatformInvitationStatus = 'Pending' | 'Accepted' | 'Revoked' | 'Expired';

/** Setting value type. C#: Domain.Constants.PlatformSettingValueTypes / CK_PLATFORM_SETTING_ValueType. */
export type PlatformSettingValueType = 'BOOLEAN' | 'INTEGER' | 'DECIMAL' | 'STRING';

/** Seller (organization) type. C#: MarketplaceSellerService.BecomeSellerAsync validation. */
export type SellerType = 'INDIVIDUAL' | 'BUSINESS';

/** Seller organization status (SQL 024). */
export type SellerStatus = 'ACTIVE' | 'SUSPENDED';

/** Seller verification status (SQL 024). */
export type SellerVerificationStatus = 'UNVERIFIED' | 'PENDING' | 'VERIFIED' | 'REJECTED';

/** Seller onboarding status (SQL 024). UNDER_REVIEW is accepted but never set by this service. */
export type SellerOnboardingStatus = 'DRAFT' | 'SUBMITTED' | 'UNDER_REVIEW' | 'COMPLETED';

/** Seller document verification status. Only 'UNVERIFIED' is written by this service. */
export type SellerDocumentVerificationStatus = 'UNVERIFIED';

/** Admin review action. C#: AdminMarketplaceSellersController.VerifySeller (case-sensitive). */
export type AdminSellerReviewAction = 'APPROVE' | 'REJECT';

/** Per-item error codes in batch invite results. C#: PlatformInvitationService.BatchCreateInvitationsAsync. */
export type BatchInviteItemError =
  | 'DUPLICATE_EMAIL_IN_BATCH'
  | 'INVITATION_ALREADY_PENDING'
  | 'INVALID_ROLE'
  | 'ROLE_ASSIGNMENT_FORBIDDEN'
  | 'INTERNAL_SERVER_ERROR';

/** Known `ErrorResponse.error` codes returned by this service (E1/E3). */
export type UserOrganizationErrorCode =
  | 'FORBIDDEN'
  | 'INTERNAL_SERVER_ERROR'
  | 'UNKNOWN_ERROR'
  | 'ROLE_NOT_FOUND'
  | 'DUPLICATE_ROLE_CODE'
  | 'SYSTEM_ROLE_PROTECTED'
  | 'SYSTEM_ROLE_PERMISSIONS_PROTECTED'
  | 'INVALID_PERMISSION'
  | 'USER_NOT_FOUND'
  | 'INVALID_ROLE'
  | 'LAST_SUPER_ADMIN_REQUIRED'
  | 'INVITATION_ALREADY_PENDING'
  | 'ROLE_ASSIGNMENT_FORBIDDEN'
  | 'INVITATION_NOT_FOUND'
  | 'INVITATION_ALREADY_ACCEPTED'
  | 'INVITATION_REVOKED'
  | 'INVITATION_EXPIRED'
  | 'INVITATION_EMAIL_MISMATCH'
  | 'INVALID_INVITATION_TOKEN'
  | 'INVALID_EMAIL'
  | 'EMAIL_NOT_VERIFIED'
  | 'INVALID_USER'
  | 'SETTING_NOT_FOUND'
  | 'SETTING_VALUE_INVALID'
  | 'SETTING_NOT_EDITABLE'
  | 'FEATURE_FLAG_NOT_FOUND'
  | 'VERSION_CONFLICT'
  | 'INVALID_ACTION';

